<?php
declare(strict_types=1);
function playlist_input_fields(array $raw,bool $creating=false): array {
    if(array_diff(array_keys($raw),['name','description','kind','rules','expectedRev']))fail('validation','Playlist visibility has its own control.');$fields=[];if($creating||array_key_exists('name',$raw))$fields['name']=input_text($raw['name']??null,'Playlist name',200,true);if($creating||array_key_exists('description',$raw))$fields['description']=input_text($raw['description']??null,'Description',2000);
    if(array_key_exists('kind',$raw)){if(!in_array($raw['kind'],['manual','smart'],true))fail('validation','Choose a manual or smart playlist.');$fields['kind']=$raw['kind'];}if(array_key_exists('rules',$raw)){if($raw['rules']!==null&&!$raw['rules'] instanceof stdClass)fail('validation','Use an object for smart playlist rules.');$rules=$raw['rules']===null?null:json_encode($raw['rules'],JSON_THROW_ON_ERROR);if($rules&&strlen($rules)>65536)fail('too_large','Use fewer smart playlist rules.',413);$fields['rules']=$rules;}return $fields;
}
function playlist_position(mixed $value): float {if((!is_int($value)&&!is_float($value))||!is_finite((float)$value)||abs((float)$value)>2**40)fail('validation','Use a valid playlist position.');return (float)$value;}
function playlists_routes(PDO $db,array $auth,string $path,string $method): bool {
    if(!preg_match('~^/api/playlists(?:/([0-9A-HJKMNP-TV-Z]{26})(?:/items(?:/([0-9A-HJKMNP-TV-Z]{26}))?)?)?$~',$path,$match))return false;$pid=$match[1]??null;$itemsPath=str_contains($path,'/items');$uid=$auth['user']['id'];
    if($method==='GET'){
        if(!$pid)reply(['items'=>query_all($db,"SELECT * FROM playlists WHERE deleted=0 AND(owner_id=? OR visibility='public') ORDER BY updated_at DESC LIMIT 2000",[$uid]),'nextCursor'=>null]);$playlist=query_one($db,'SELECT * FROM playlists WHERE id=? AND deleted=0',[$pid]);if(!$playlist)fail('not_found','Playlist not found.',404);if($playlist['owner_id']!==$uid&&$playlist['visibility']!=='public')fail('forbidden','This playlist is private.',403);$items=query_all($db,"SELECT i.* FROM playlist_items i JOIN tracks t ON t.id=i.track_id WHERE i.playlist_id=? AND i.deleted=0 AND t.deleted=0 AND(t.owner_id=? OR t.visibility='public') ORDER BY i.position,i.id",[$pid,$uid]);reply($itemsPath?['items'=>$items,'nextCursor'=>null]:['playlist'=>$playlist,'items'=>$items]);
    }
    $action=!$pid&&$method==='POST'?'create':($pid&&!$itemsPath&&$method==='PATCH'?'edit':($pid&&!$itemsPath&&$method==='DELETE'?'delete':($pid&&$itemsPath&&$method==='POST'?'add':($pid&&$itemsPath&&$method==='PATCH'?'reorder':($pid&&$itemsPath&&$method==='DELETE'?'remove':null)))));if(!$action)return false;$raw=str_contains($_SERVER['CONTENT_TYPE']??'','application/json')?metadata_object(metadata_json_body(),'Request'):[];if(isset($match[2]))$raw['trackId']=$match[2];$now=now_ms();$ops=[];$updated=0;
    if($action==='create'){$fields=playlist_input_fields($raw,true);$row=['id'=>ulid(),'rev'=>0,'owner_id'=>$uid,'name'=>$fields['name'],'description'=>$fields['description'],'kind'=>'manual','rules'=>null,'cover_key'=>null,'visibility'=>'private','sync_visibility'=>0,'created_at'=>$now,'updated_at'=>$now,'deleted'=>0,...$fields];$result=journal_write($db,$auth,['summary'=>'Created playlist '.$row['name'],'ops'=>[['table'=>'playlists','id'=>$row['id'],'before'=>null,'after'=>$row]]]);reply([...$result,'playlistId'=>$row['id'],'updated'=>1],201);}
    $playlist=query_one($db,'SELECT * FROM playlists WHERE id=? AND deleted=0',[$pid]);if(!$playlist)fail('not_found','Playlist not found.',404);if($playlist['owner_id']!==$uid)fail('forbidden','Choose a playlist that belongs to you.',403);if(array_key_exists('expectedRev',$raw)&&((!is_int($raw['expectedRev'])&&!is_float($raw['expectedRev']))||floor((float)$raw['expectedRev'])!==(float)$raw['expectedRev']||(int)$raw['expectedRev']!==(int)$playlist['rev']))journal_conflict([['table'=>'playlists','id'=>$pid]]);
    if($action==='edit'){$op=journal_op('playlists',$playlist,[...$playlist,...playlist_input_fields($raw)]);if($op)$ops[]=$op;$result=journal_write($db,$auth,['summary'=>'Updated playlist '.$playlist['name'],'ops'=>$ops]);reply([...$result,'playlistId'=>$pid,'updated'=>$op?1:0]);}
    $items=query_all($db,'SELECT id,rev,owner_id,playlist_id,track_id,position,added_at,deleted FROM playlist_items WHERE playlist_id=?',[$pid]);$live=array_values(array_filter($items,fn($row)=>!$row['deleted']));usort($live,fn($a,$b)=>$a['position']<=>$b['position']?:strcmp($a['id'],$b['id']));
    if($action==='delete'){$ops[]=['table'=>'playlists','id'=>$pid,'before'=>['id'=>$pid,'rev'=>$playlist['rev'],'deleted'=>0],'after'=>['id'=>$pid,'rev'=>$playlist['rev'],'deleted'=>1]];foreach($live as $row)$ops[]=['table'=>'playlist_items','id'=>$row['id'],'before'=>['id'=>$row['id'],'rev'=>$row['rev'],'deleted'=>0],'after'=>['id'=>$row['id'],'rev'=>$row['rev'],'deleted'=>1]];$result=journal_write($db,$auth,['summary'=>'Deleted playlist '.$playlist['name'],'ops'=>$ops]);reply([...$result,'playlistId'=>$pid,'updated'=>count($live)]);}
    if($action==='add'){
        $ids=journal_ids($raw['trackIds']??null);$tracks=[];foreach(array_chunk($ids,200)as $group)$tracks=array_merge($tracks,query_all($db,'SELECT id,owner_id,visibility FROM tracks WHERE deleted=0 AND id IN('.implode(',',array_fill(0,count($group),'?')).')',$group));if(count($tracks)!==count($ids))fail('not_found','A selected track was not found.',404);foreach($tracks as $track)if($track['owner_id']!==$uid&&$track['visibility']!=='public')fail('forbidden','A selected track is no longer shared.',403);
        $liveIds=array_column($live,'track_id');$adding=array_values(array_diff($ids,$liveIds));$after=array_key_exists('afterPosition',$raw)?playlist_position($raw['afterPosition']):($live?(float)$live[count($live)-1]['position']:0);$next=null;foreach($live as $row)if($row['position']>$after){$next=$row;break;}$step=$next?((float)$next['position']-$after)/(count($adding)+1):1;if($adding&&$step<PHP_FLOAT_EPSILON*max(1,abs($after)))fail('conflict','Reorder this playlist before inserting more tracks here.',409);$previous=array_column($items,null,'track_id');
        foreach($adding as $index=>$trackId){$before=$previous[$trackId]??null;$row=['id'=>$pid.':'.$trackId,'rev'=>$before['rev']??0,'owner_id'=>$uid,'playlist_id'=>$pid,'track_id'=>$trackId,'position'=>$after+$step*($index+1),'added_at'=>$now,'deleted'=>0];$op=journal_op('playlist_items',$before,$row);if($op){$ops[]=$op;$updated++;}}$summary='Added '.$updated.' tracks to playlist '.$playlist['name'];
    }elseif($action==='remove'){$ids=journal_ids($raw['trackIds']??[$raw['trackId']??null]);foreach($live as $row)if(in_array($row['track_id'],$ids,true)){$ops[]=['table'=>'playlist_items','id'=>$row['id'],'before'=>['id'=>$row['id'],'rev'=>$row['rev'],'deleted'=>0],'after'=>['id'=>$row['id'],'rev'=>$row['rev'],'deleted'=>1]];$updated++;}$summary='Removed '.$updated.' tracks from playlist '.$playlist['name'];}
    else{$moves=[];if(array_key_exists('trackIds',$raw))foreach(journal_ids($raw['trackIds'])as $index=>$id)$moves[]=['trackId'=>$id,'position'=>$index+1];else $moves[]=['trackId'=>journal_ids([$raw['trackId']??null])[0],'position'=>playlist_position($raw['position']??null)];$byId=array_column($live,null,'track_id');foreach($moves as $move){$row=$byId[$move['trackId']]??null;if(!$row)fail('not_found','This track is not in the playlist.',404);$op=journal_op('playlist_items',$row,[...$row,'position'=>$move['position']]);if($op){$ops[]=$op;$updated++;}}$summary='Reordered playlist '.$playlist['name'];}
    if($ops)array_unshift($ops,['table'=>'playlists','id'=>$pid,'before'=>['id'=>$pid,'rev'=>$playlist['rev']],'after'=>['id'=>$pid,'rev'=>$playlist['rev']]]);$result=journal_write($db,$auth,['summary'=>$summary,'ops'=>$ops,...($action==='add'&&isset($raw['changeId'])?['appendTo'=>journal_ids([$raw['changeId']],'Action ID')[0]]:[])]);reply([...$result,'playlistId'=>$pid,'updated'=>$updated]);
}
